from __future__ import annotations

import json
import logging
import re
import time
from pathlib import Path
from typing import Any

EMIL_MSG_FILTERS_REGEX = re.compile(
    r"((0x[0-9a-f]+)-?(0x[0-9a-f]+)?(:\d+)?)", re.IGNORECASE
)


def hex_range_to_set(hex_range: list[str]) -> set[str]:
    """Convert a hex range into a set of individual hex values."""
    hex_set = set()
    for hex_value in hex_range:
        if "-" in hex_value:
            start, end = (int(h, 16) for h in hex_value.replace(" ", "").split("-"))
            hex_set.update(hex(i) for i in range(start, end + 1))
        else:
            hex_set.add(hex_value)
    return hex_set


def union_hex_ranges(*lists: list[str]) -> list[str]:
    """Perform a union operation on two lists of hex ranges."""
    union_set = {
        single_hex for hex_list in lists for single_hex in hex_range_to_set(hex_list)
    }
    return sorted(union_set)


def hex_values_to_ranges(hex_values: list[str]) -> list[str]:
    """Convert a list of individual hex values back into hex ranges."""
    hex_ranges = []
    current_range = [hex_values[0]]
    for hex_value in hex_values[1:]:
        if int(hex_value, 16) == int(current_range[-1], 16) + 1:
            current_range.append(hex_value)
        else:
            hex_ranges.append((current_range[0], current_range[-1]))
            current_range = [hex_value]
    hex_ranges.append((current_range[0], current_range[-1]))
    hex_ranges = [
        f"{start}-{end}" if start != end else start for start, end in hex_ranges
    ]
    return hex_ranges


def merge_hex_lists(*hex_lists: list[str]) -> list[str]:
    """Merge a list of hex ranges."""
    if not any(hex_lists):
        return []
    return hex_values_to_ranges(union_hex_ranges(*hex_lists))


def save_emil_data_to_file(
    emil_data: dict[str, dict[str, list[str]]], file_path: str | Path
) -> None:
    """Save EMIL data to a file."""
    file_path = Path(file_path) if isinstance(file_path, str) else file_path
    with Path(file_path).open("w") as file:
        json.dump(emil_data, file, indent=4)


def get_emil_data_from_file(file_path: str | Path) -> dict[str, dict[str, list[str]]]:
    """Get EMIL data from a file."""
    file_path = Path(file_path) if isinstance(file_path, str) else file_path
    if file_path.exists():
        with file_path.open("r") as file:
            return json.load(file)
    return {}


def change_emil_stop_docker_inside_suite_scope(
    plugins: dict, new_stop_flag: bool
) -> dict:
    if "emil" in plugins:
        for vm_no, emil_data in plugins["emil"]["kwargs"].items():
            plugins["emil"]["kwargs"][vm_no]["stop_docker"] = new_stop_flag
    return plugins


def repeat(
    func: callable,
    *args,
    timeout: float,
    logger: logging.Logger,
    log_nth: int = 10,
    sleep_time: float = 1,
    **kwargs,
) -> Any:
    log_counter = 0
    start_time = time.time()
    while (time.time() - start_time) < timeout:
        try:
            result, status, msg = func(*args, **kwargs)
            if result is True:
                logger.info(msg)
                return status
            if log_counter % log_nth == 0:
                logger.debug(msg)
            log_counter += 1
        except Exception as err:
            logger.debug(err, exc_info=True)
        time.sleep(sleep_time)
    raise TimeoutError(f"'{func.__name__}' did not finish in time.")
